public class RemoveElement {

    // ---- 解法一：快慢指针（保序，面试首选）----
    public int removeElement(int[] nums, int val) {
        int slow = 0;
        for (int fast = 0; fast < nums.length; fast++) {
            if (nums[fast] != val) {
                nums[slow] = nums[fast];
                slow++;
            }
        }
        return slow;
    }

    // ---- 解法二：尾部交换（不保序，写入少）----
    public int removeElementSwap(int[] nums, int val) {
        int left = 0, right = nums.length;
        while (left < right) {
            if (nums[left] == val) {
                nums[left] = nums[right - 1]; // 用尾部元素填补
                right--;
            } else {
                left++;
            }
        }
        return left;
    }

    // ---- 测试 ----
    public static void main(String[] args) {
        RemoveElement s = new RemoveElement();

        // 用例 1：nums=[3,2,2,3], val=3 → 新长度 2，前两个元素 2,2
        int[] nums1 = {3, 2, 2, 3};
        int len1 = s.removeElement(nums1, 3);
        System.out.println("快慢指针: len=" + len1);
        for (int i = 0; i < len1; i++) System.out.print(nums1[i] + " ");
        System.out.println();

        // 用例 2：nums=[0,1,2,2,3,0,4,2], val=2 → 新长度 5
        int[] nums2 = {0, 1, 2, 2, 3, 0, 4, 2};
        int len2 = s.removeElement(nums2, 2);
        System.out.println("快慢指针: len=" + len2);
        for (int i = 0; i < len2; i++) System.out.print(nums2[i] + " ");
        System.out.println();

        // 用例 3：尾部交换，val 少时写入更少
        int[] nums3 = {0, 1, 2, 2, 3, 0, 4, 2};
        int len3 = s.removeElementSwap(nums3, 2);
        System.out.println("尾部交换: len=" + len3);
        for (int i = 0; i < len3; i++) System.out.print(nums3[i] + " ");
        System.out.println();

        // 用例 4：空数组
        int[] nums4 = {};
        System.out.println("空数组: len=" + s.removeElement(nums4, 1));

        // 用例 5：全部是 val
        int[] nums5 = {1, 1, 1};
        System.out.println("全val: len=" + s.removeElement(nums5, 1));
    }
}
